// Keygen-music synthesis, written natively.
//
// The logic of keygen music is a volume argument: the score is data (a list of note events, a few
// kilobytes), the sound is generated by code on demand, and no audio file is stored at all. This
// module is the generator half: oscillators (sine / square / saw / triangle) with a per-note ADSR
// envelope, mixing by summation with a hard clamp at the unit range. The score comes in, PCM comes
// out; what the caller does with the PCM (play it, or hand it to the FLAC/WAV writers) is the
// caller's business, which is what keeps the player and the data apart.
export const capabilities = {
  id: "synth",
  kohaneName: "Kohane Bassline Keygen Synth",
  container: "none",
  read: { level: "none", detail: "this module generates; scores are plain note-event data" },
  decode: { level: "none", detail: "not applicable" },
  encode: { level: "partial", detail: "programmatic synthesis: sine, square, saw and triangle oscillators with a per-note ADSR envelope; output is interleaved float PCM in -1..1, mono" },
  verifiedAgainst: "sample-exact check of the ADSR envelope segments and oscillator shapes, the peak bound, and a round trip through the project's own FLAC writer and independent walk (tools/flac-walk.mjs)",
};

const MIDDLE_A = 440;

export function pitchHz(pitch) {
  return MIDDLE_A * 2 ** ((pitch - 69) / 12);
}

const WAVES = {
  sine: (phase) => Math.sin(2 * Math.PI * phase),
  square: (phase) => (phase < 0.5 ? 1 : -1),
  saw: (phase) => 1 - 2 * phase,
  triangle: (phase) => 4 * Math.abs(phase - 0.5) - 1,
};

// The noise wave needs per-note state, so it is special-cased in the render loop instead of living
// in the pure phase table. One xorshift32 state per note, seeded deterministically from the note's
// pitch, so the same score renders the same noise on every run - which is exactly what a second
// implementation (the C player embedded in an exe) needs to match sample for sample.
const noiseSeed = (pitch, index) => (((pitch * 2654435761) ^ (index * 40503)) >>> 0) || 1;
const nextNoise = (state) => {
  let x = state[0];
  x ^= x << 13; x >>>= 0;
  x ^= x >>> 17;      // logical shift, matching a C uint32_t: an arithmetic >> would fill ones
  x ^= x << 5; x >>>= 0;
  state[0] = x;
  return x / 0xffffffff;
};

// One voice's envelope state. Attack rises linearly to 1, decay falls linearly to the sustain
// level, sustain holds, release falls linearly to zero. A note cut short enters release from
// wherever the envelope currently is, so there is no click at the end of a short note.
function envelopeAt(env, t, dur) {
  const { a, d, s, r } = env;
  const gate = Math.min(t, dur);
  let level;
  if (gate <= a) level = a > 0 ? gate / a : 1;
  else if (gate <= a + d) level = d > 0 ? 1 - ((gate - a) / d) * (1 - s) : s;
  else level = s;
  if (t > dur) {
    // A frame landing within floating-point dust of the release end counts as finished, so the
    // last frame of a note is exactly silent instead of carrying a 1e-16 remainder.
    let rel = (t - dur) / r;
    if (rel > 1 - 1e-9) rel = 1;
    level *= 1 - rel;
  }
  return level;
}

/**
 * A MIDI score as readMidiScore reports it (tick-space) becomes what synthesize eats (seconds):
 * one note event per note, with the velocity folded into 0..1. The synth itself stays tick-blind -
 * whoever reads the score converts time, and this is that conversion, in the one place that owns
 * the synth's input shape.
 */
export function midiToSynth(score) {
  const ppq = Number(score.ppq) || 480;
  const tempo = Number(score.tempo) || 120;
  const secPerTick = 60 / (tempo * ppq);
  const notes = [];
  for (const track of score.tracks || []) {
    for (const n of track.notes || []) {
      notes.push({
        t: (n.tick || 0) * secPerTick,
        dur: Math.max(0, (n.ticks || 0) * secPerTick),
        pitch: n.note,
        vel: (Number(n.velocity) || 0) / 127,
      });
    }
  }
  notes.sort((a, z) => a.t - z.t);
  return { notes, tempo, ppq, source: score.path || null };
}

/**
 * Synthesise a score into interleaved float PCM in -1..1 (mono).
 * score: { sampleRate?, notes: [{t, dur, pitch, vel?, wave?}], wave?, adsr? }
 *   t/dur in seconds, pitch as a MIDI key, vel in 0..1, wave one of sine/square/saw/triangle.
 *   adsr: { a, d, s, r } - attack/decay/release in seconds, sustain as a level in 0..1.
 * Returns { samples: Float64Array, frames, sampleRate, notes, lastEndSec, peaks: {min, max} }.
 */
export function synthesize(score) {
  const sampleRate = Number(score.sampleRate) || 44100;
  const defaultWave = String(score.wave || "square");
  const env = Object.assign({ a: 0.005, d: 0.08, s: 0.7, r: 0.05 }, score.adsr || {});
  const notes = Array.isArray(score.notes) ? score.notes : [];
  if (!notes.length) throw new Error("a score needs at least one note");

  let end = 0;
  const prepared = notes.map((n, ni) => {
    const t = Math.max(0, Number(n.t) || 0);
    const dur = Math.max(0, Number(n.dur) || 0);
    const pitch = Number(n.pitch);
    if (!Number.isFinite(pitch)) throw new Error("every note needs a pitch");
    const vel = n.vel === undefined ? 1 : Math.max(0, Math.min(1, Number(n.vel) || 0));
    const waveName = String(n.wave || defaultWave);
    const wave = WAVES[waveName] || null;
    if (!wave && waveName !== "noise") throw new Error(`unknown wave "${n.wave || defaultWave}" (sine, square, saw, triangle, noise)`);
    const noteEnd = t + dur + env.r;
    if (noteEnd > end) end = noteEnd;
    return { t, dur, pitch, vel, wave, waveName, phase: 0, noise: waveName === "noise" ? [noiseSeed(pitch, ni)] : null };
  });

  const frames = Math.ceil(end * sampleRate);
  const samples = new Float64Array(frames);
  for (const n of prepared) {
    const freq = pitchHz(n.pitch);
    const step = freq / sampleRate;
    for (let i = Math.floor(n.t * sampleRate); i < frames; i++) {
      const t = i / sampleRate;
      if (t > n.t + n.dur + env.r) break;
      const level = envelopeAt(env, t - n.t, n.dur) * n.vel;
      if (level === 0 && t > n.t + n.dur) continue;
      const wv = n.noise ? nextNoise(n.noise) * 2 - 1 : n.wave(n.phase);
      samples[i] += wv * level;
      n.phase += step;
      if (n.phase >= 1) n.phase -= Math.floor(n.phase);
    }
  }

  let peakMin = 0, peakMax = 0;
  for (let i = 0; i < frames; i++) {
    if (samples[i] > 1) samples[i] = 1;
    else if (samples[i] < -1) samples[i] = -1;
    if (samples[i] < peakMin) peakMin = samples[i];
    if (samples[i] > peakMax) peakMax = samples[i];
  }

  return { samples, frames, sampleRate, notes: prepared.length, lastEndSec: end, peaks: { min: peakMin, max: peakMax } };
}
